import React, { useMemo, memo } from 'react';
import { map, round } from 'lodash';
import classNames from 'classnames';
import { Card, Tooltip } from 'antd';
import { ArrowUpOutlined } from '@ant-design/icons';
import useScreenStatistics from 'components/features/heatmaps/hooks/useScreenStatistics';
import { compactNotation } from 'Utils/helpers/commonUtils';
import InActiveSVG from 'components/common/Analytics/OverviewBoxes/BoxSVG/InActiveSVG';
import { HeatmapsScreenStatisticsStyled } from '../HeatmapStyled';

const issueFieldWithTitle = [
  'Visits with UI freezes',
  'Visits with rage taps',
  'Visits with crashes',
  'App quit rate',
];

const HeatmapsScreenStatistics = memo(() => {
  const statistics = useScreenStatistics();
  const renderScreenStatistics = useMemo(() => {
    let component = <></>;
    component = (
      <HeatmapsScreenStatisticsStyled>
        {map(statistics, (statistic, key) => (
          <DataCard statistic={statistic} key={key} title={key} />
        ))}
      </HeatmapsScreenStatisticsStyled>
    );
    return component;
  }, [statistics]);
  return <>{renderScreenStatistics}</>;
});

const DataCard = memo(
  ({
    title: cardTitle,
    statistic: { display, tooltipTitle, valueThisPeriod, valuePreviousPeriod },
  }) => {
    const percentChange = useMemo(() => {
      let data;
      if (valuePreviousPeriod === -1 || valueThisPeriod === -1) data = null;
      else if (valuePreviousPeriod === 0 && valueThisPeriod > 0) data = 'inf';
      else
        data = round(
          ((valueThisPeriod - valuePreviousPeriod) / valuePreviousPeriod) * 100,
          1
        );
        if(data === Infinity) data = 'inf'
      return data ? String(data) : null;
    }, [valuePreviousPeriod, valueThisPeriod]);
    let displayCopy = display;
    if (valueThisPeriod === -1) displayCopy = '-';
    const hasIssueTitle =  useMemo(()=> issueFieldWithTitle.indexOf(cardTitle) > -1, [cardTitle]);

    return (
        <Card
          className="box-item"
          data-intercom-target={cardTitle}
        >
          <Tooltip title={tooltipTitle} placement='bottom' align={{offset: [0, -16]}}>
            <div className="ant-card-head">
              <div className="ant-card-head-wrapper">
                <div className="ant-card-head-title">
                  <div className="overview-card-heading">
                    <div className="icon-box">
                      <InActiveSVG mainKey={cardTitle} />
                    </div>
                    <span>
                      <span className="stat-card-title">
                        {cardTitle}
                        {/* <Tooltip title={tooltipTitle}>{cardTitle}</Tooltip> */}
                      </span>
                        {' '}
                      <span className="stat-title">
                        <PercentageTag
                          percentChange={percentChange}
                          isIssues={
                            hasIssueTitle
                          }
                        />{' '}
                      </span>
                    </span>
                  </div>
                </div>
              </div>
            </div>
            <div className="stat-flex-wrapper">
                <Content display={displayCopy} />
            </div>
          </Tooltip>
        </Card>
    );
  }
);

const PercentageTag = memo(({ percentChange, isIssues }) => {
  let value
  const isNullish = ['null', '0', null].indexOf(percentChange) > -1;
  if (percentChange && !isNullish) {
    value = `${!percentChange.includes('-') ? '+' : ''}${
      percentChange !== 'inf'
        ? compactNotation(round(percentChange, 1))
        : percentChange
    }%`;
    if(value.includes('inf')) value = <ArrowUpOutlined className='heatmaps-stat-up-icon' />
    return (
      <span
        className={classNames('stat-percent', {
          'stat-down': isIssues
            ? !percentChange.includes('-')
            : percentChange.includes('-'),
          'stat-up': isIssues
            ? percentChange.includes('-')
            : !percentChange.includes('-'),
        })}
      >
        {value}
      </span>
    );
  }
  return <></>;
});
const Content = memo(({ display }) => (
  <div className="stat-flex stat-flex-1">
    <span className="stat-content">
      <h2>{display}</h2>
    </span>
  </div>
));
export default HeatmapsScreenStatistics;
