import React, { useMemo, useCallback } from 'react';
import { useSelector } from 'react-redux';
import moment from 'moment/moment';
import { useHeatmapScreenStats } from 'components/features/heatmaps/hooks';
import { compactNotation, convertGetTime, preciseNumber } from 'Utils/helpers/commonUtils';
import { formattedFilters } from 'Utils/ScreenPageFilter'
import { formatNumberWithCommas } from 'Utils/helpers/numberFormatter';

const useScreenStatistics = () => {
  const {
    urlReducer: { appId: appid, screenname },
    appFilter: {
      dateSegment,
      heatmap: { segment: filters },
    },
  } = useSelector(({ urlReducer, appFilter }) => ({
    urlReducer,
    appFilter,
  }));
  const heatmapScreenStatsPayload = useMemo(
    () => ({
      appid,
      screen_name: screenname,
      mega_filters: formattedFilters(filters) || [],
      date_range: dateSegment,
    }),
    [appid, screenname, filters, dateSegment]
  );

  const heatmapScreenStatsPayloadPrev = useMemo(
    () => ({
      appid,
      screen_name: screenname,
      mega_filters: formattedFilters(filters) || [],
      date_range : {
        ...dateSegment,
        value: {
          lower: (
            moment.unix(
              (Math.round(new Date(dateSegment.value.lower).getTime()) - moment(dateSegment.value.upper).diff(dateSegment.value.lower)) /
                1000
            )
          ),
          upper: (moment(dateSegment.value.lower).utc().format())
        }
      }
    }),
    [appid, screenname, filters, dateSegment]
  );
  const { data: heatmapScreenStatsData } = useHeatmapScreenStats( heatmapScreenStatsPayload, 'heatmap-screen-stats' );
  const { data: heatmapScreenStatsDataPrev } = useHeatmapScreenStats( heatmapScreenStatsPayloadPrev, 'heatmap-screen-stats-prev' );
  const checkText = useCallback(
    (data) => ['loading...', '-'].indexOf(data) > -1,
    []
  );
  const tooltipContent = useCallback((boldText, rest) => (
    <>
      <b>{boldText}</b>
      {rest}
    </>
  ), []);
  const statistics = useMemo(() => {
    const {
      avgTimeOnScreen = '-',
      userCount = '-',
      count = '-',
      uiFreezeRate = '-',
      rageTapRate = '-',
      exitRate = '-',
      avgGestureCount = '-',
      crashPercentage = '-',
      this_period_date_string: thisPeriodDateString,
    } = heatmapScreenStatsData?.data || {};

    const {
      avgTimeOnScreen: avgTimeOnScreenPrev,
      userCount: userCountPrev,
      count: countPrev,
      uiFreezeRate: uiFreezeRatePrev,
      rageTapRate: rageTapRatePrev,
      exitRate: exitRatePrev,
      avgGestureCount: avgGestureCountPrev,
      crashPercentage: crashPercentagePrev,
    } = heatmapScreenStatsDataPrev?.data || {};
    const getDataCopy = (data) => !checkText(data) ? compactNotation(data, 2) : data;
    const getDataPercent = (data, isTooltip = false) => {
      const dataCopy = preciseNumber(data, 2, isTooltip);
      return !checkText(data) ? `${dataCopy}%` : data
    };
    return {
      'Screen visits': {
        display: count !== 'loading...' ? getDataCopy(count): count,
        valueThisPeriod: count,
        valuePreviousPeriod: countPrev,
        tooltipTitle: tooltipContent(count !== 'loading...' && formatNumberWithCommas(count), ` times on total, users visited the screen during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      Users: {
        display: getDataCopy(userCount),
        valueThisPeriod: userCount,
        valuePreviousPeriod: userCountPrev,
        tooltipTitle: tooltipContent(userCount !== 'loading...' && formatNumberWithCommas(userCount), ` total distinct users visited the screen during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'Visit duration': {
        display:
          avgTimeOnScreen !== 'loading...'
            ? avgTimeOnScreen < 60 ? `${Math.round(avgTimeOnScreen)} sec` : convertGetTime({ durationInSecs: avgTimeOnScreen })
            : avgTimeOnScreen,
        valueThisPeriod: avgTimeOnScreen,
        valuePreviousPeriod: avgTimeOnScreenPrev,
        tooltipTitle: tooltipContent(avgTimeOnScreen !== 'loading...'
        ? avgTimeOnScreen < 60 ? `${Math.round(avgTimeOnScreen)} sec` : convertGetTime({ durationInSecs: avgTimeOnScreen })
        : avgTimeOnScreen, ` on average, users spent time on the screen during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'Gestures on screen': {
        display:  avgGestureCount !== 'loading...' ? preciseNumber(avgGestureCount, 2) : avgGestureCount,
        valueThisPeriod: avgGestureCount,
        valuePreviousPeriod: avgGestureCountPrev,
        tooltipTitle: tooltipContent(avgGestureCount !== 'loading...' && preciseNumber(avgGestureCount, 2), ` times on average, users made gestures on the screen during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'App quit rate': {
        display: getDataPercent(exitRate),
        valueThisPeriod: +exitRate,
        valuePreviousPeriod: +exitRatePrev,
        tooltipTitle: tooltipContent(exitRate !== 'loading...' && getDataPercent(exitRate, true), ` of screen visits, users quit the app during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'Visits with rage taps': {
        display: getDataPercent(rageTapRate),
        valueThisPeriod: +rageTapRate,
        valuePreviousPeriod: +rageTapRatePrev,
        tooltipTitle: tooltipContent(rageTapRate !== 'loading...' && getDataPercent(rageTapRate, true), ` of screen visits with rage taps during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'Visits with crashes': {
        display: getDataPercent(crashPercentage),
        valueThisPeriod: +crashPercentage,
        valuePreviousPeriod: +crashPercentagePrev,
        tooltipTitle: tooltipContent(crashPercentage !== 'loading...' && getDataPercent(crashPercentage, true), ` of screen visits with crashes during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
      'Visits with UI freezes': {
        display: getDataPercent(uiFreezeRate),
        valueThisPeriod: +uiFreezeRate,
        valuePreviousPeriod: +uiFreezeRatePrev,
        tooltipTitle: tooltipContent(uiFreezeRate !== 'loading...' && getDataPercent(uiFreezeRate, true), ` screen visits with UI freezes during ${ thisPeriodDateString || 'the selected date range.' }`)
      },
    };
  }, [checkText, heatmapScreenStatsData?.data, heatmapScreenStatsDataPrev?.data, tooltipContent]);
  return statistics;
};
export default useScreenStatistics
